package com.lamggm.rospocket;
import android.app.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=31) @LooperMode(LooperMode.Mode.PAUSED)
public class GaugeActivityTest {
 final ConnectionActivityTest f=new ConnectionActivityTest();
 @Before public void setup()throws Exception{f.setup();} @After public void cleanup()throws Exception{f.cleanup();}
 View root(){return f.a.getWindow().getDecorView();} DashboardBoard board(){return root().findViewWithTag("dashboard-board");}
 AlertDialog open(){board().edit();root().findViewWithTag("layout-options:watch0").performClick();AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();ListView list=d.getListView();int at=-1;for(int i=0;i<list.getCount();i++)if(list.getItemAtPosition(i).toString().equals("Visualização da leitura…"))at=i;assertTrue("Watch editor must offer visualization",at>=0);list.performItemClick(list.getAdapter().getView(at,null,list),at,at);f.paint();return ShadowAlertDialog.getLatestAlertDialog();}
 @Test public void extraSlotsUseTheirOwnTypedFieldAndReplacementCannotReuseTheOldSample()throws Exception{WatchSlots slots=(WatchSlots)f.get("watchSlots");DashboardLayout layout=DashboardLayout.defaults();JSONArray rows=new JSONArray().put(new JSONObject());for(int i=1;i<4;i++){WatchSlots.Request r=slots.request(i,"rt/extra"+i,"std_msgs::msg::dds_::Float64_",false,false);slots.complete(r,"");layout=layout.display("watch"+i,new DashboardLayout.Display("bar","data",0,100,"V"));rows.put(new JSONObject().put("readerActive",true).put("fresh",true).put("count",3).put("matched",1).put("age",0).put("subscriptionState","receiving").put("numericFields",new JSONArray().put(new JSONObject().put("path","data").put("state","finite").put("value",i*11))));}board().bind(layout,null);WatchSlots.Frame[] frames=slots.frames();f.call("renderExtras",new Class<?>[]{JSONObject.class,WatchSlots.Frame[].class,long.class},new JSONObject().put("watches",rows),frames,System.nanoTime());f.call("refreshDashboard",new Class<?>[]{});for(int i=1;i<4;i++){MetricCard c=root().findViewWithTag("watch-card:"+i);String text=c.getContentDescription().toString();assertTrue(text,text.contains(String.format(java.util.Locale.ROOT,"%.5g",i*11.0)));}slots.request(2,"rt/new","std_msgs::msg::dds_::Float64_",false,false);f.call("refreshDashboard",new Class<?>[]{});MetricCard c=root().findViewWithTag("watch-card:2");assertFalse(c.getContentDescription().toString().contains("22.000"));}
 @Test public void invalidScaleKeepsDialogAndLateConfirmationCannotChangeNewOwner()throws Exception{AlertDialog d=open();((EditText)d.findViewById(android.R.id.content).findViewWithTag("display-min")).setText("100");((EditText)d.findViewById(android.R.id.content).findViewWithTag("display-max")).setText("0");d.getButton(-1).performClick();f.paint();assertTrue(d.isShowing());assertTrue(((TextView)d.findViewById(android.R.id.content).findViewWithTag("display-error")).getText().length()>0);board().cancel();board().edit();String before=board().layout().encode();((EditText)d.findViewById(android.R.id.content).findViewWithTag("display-min")).setText("0");((EditText)d.findViewById(android.R.id.content).findViewWithTag("display-max")).setText("10");d.getButton(-1).performClick();f.paint();assertEquals(before,board().layout().encode());}
 @Test public void actualEditorSavesVisualizationAndActivityUsesOnlyTypedCurrentFields()throws Exception{AlertDialog d=open();((Spinner)d.findViewById(android.R.id.content).findViewWithTag("display-mode")).setSelection(1);((EditText)d.findViewById(android.R.id.content).findViewWithTag("display-max")).setText("10");d.getButton(-1).performClick();f.paint();assertTrue(board().save());assertEquals("gauge",new DashboardStore(f.a.getFilesDir()).load().get("watch0").display.mode);JSONObject s=new JSONObject(f.bridge.snapshot).put("numericFields",new JSONArray().put(new JSONObject().put("path","data").put("value",7.25).put("state","finite"))).put("last","wrong-display-text");f.bridge.snapshot=s.toString();f.set("lastUi",0L);f.tick();f.paint();MetricCard c=root().findViewWithTag("watch-card:0");String text=c.getContentDescription().toString();assertTrue(text,text.contains("gauge")&&text.contains("7.2500"));f.call("disconnect",new Class<?>[]{});assertFalse(c.getContentDescription().toString().contains("7.2500"));assertEquals(1,f.bridge.subscriptions);}
}
